// Offensive display-name filter (C++ twin of scripts/namefilter.py: same spec, same data files, same test vectors in
// tests/name_filter_vectors.txt). Used by the game to mask hateful party-member names on every viewer. Pure: no game
// state, so tests/test_name_filter.cpp builds it alone.
//
// The data (data/name_filter/*) is embedded (name_filter_data.inc, generated by tools/name_filter/gen_embed.py); a data
// folder named by BB_NAME_FILTER_DIR, or ./name_filter, or ./data/name_filter, wins when it holds the files, so the lists
// can be updated without a new build. The spec is documented at the top of scripts/namefilter.py.
#pragma once
#include <map>
#include <set>
#include <string>
#include <vector>

namespace coop::namefilter {

class NameFilter {
public:
    // texts: file name -> content, the files listed in kFiles.
    explicit NameFilter(const std::map<std::string, std::string>& texts);
    // "" when the name is fine, else the tier that caught it: "A" strict, "B" phrase, "C" code.
    std::string Reason(const std::string& utf8) const;
    bool Offensive(const std::string& utf8) const { return !Reason(utf8).empty(); }

private:
    struct Entry {
        int kind;  // 0 map, 1 drop, 2 sep, 3 upside
        std::u32string text;
    };
    std::map<char32_t, Entry> cm_;
    std::set<std::u32string> terms_[3];            // [1] folded to one letter per run, [2] runs cut to two (flag x)
    std::vector<std::u32string> terms_s_[3];
    std::map<std::u32string, int> k_;
    size_t k_max_ = 0;
    std::vector<std::u32string> c_join_, c_rawjoin_;
    std::set<std::u32string> c_raw_;
    std::vector<std::pair<std::u32string, std::vector<std::u32string>>> c_ctx_;
    std::set<char32_t> c_sym_;
    std::vector<std::pair<char32_t, char32_t>> c_sym2_;
    std::set<std::u32string> allow_w_[3];
    std::vector<std::u32string> allow_c_[3];

    std::u32string Term(const std::u32string& text, bool digits = false) const;
    void Map(const std::u32string& in, std::u32string* out, int* up) const;
    std::u32string Blank(const std::u32string& w, int form) const;
    bool Dp(const std::u32string& tok, std::vector<int>* out) const;
    std::vector<int> Elements(const std::u32string& tok) const;
    bool TierA(const std::vector<std::u32string>& blanked, int form) const;
    bool TierB(const std::vector<std::u32string>& words) const;
    const char* Scan(const std::u32string& cps) const;
    bool Codes(const std::u32string& cps) const;
};

inline const char* const kFiles[] = {"charmap.tsv", "strict.txt", "identity.txt", "people.txt",
                                     "violence.txt", "link.txt",    "codes.txt",    "allow.txt"};

// The process-wide filter (embedded data, or the data folder). Thread-safe after the first call.
const NameFilter& Default();

// Whether `name` is offensive, the tier ("" when fine), and the replacement shown for it ("Hunter 3F2").
bool Offensive(const std::string& name);
std::string Reason(const std::string& name);
std::string MaskText(const std::string& name);
// name unchanged, or its mask when the name is offensive.
std::string Masked(const std::string& name);

}  // namespace coop::namefilter
